"""LBracket_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 1 extrusion(s) and 2 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python LBracket_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along z
z1 = 2.0    # level along z
hole_d = 5.0

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: z 0.0 to 2.0 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(0.0, 0.0), P(0.0, 100.0)),
    cf.segment(P(0.0, 100.0), P(40.0, 100.0)),
    cf.segment(P(40.0, 100.0), P(40.0, 44.0)),
    Edge.makeThreePointArc(P(40.0, 44.0), P(41.4288, 40.9358), P(44.0, 40.0)),
    cf.segment(P(44.0, 40.0), P(100.0, 40.0)),
    cf.segment(P(100.0, 40.0), P(100.0, 0.0)),
    cf.segment(P(100.0, 0.0), P(0.0, 0.0)),
)
part = prism(outline_1, z0, z1)

# ---- round holes: (x, y, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (32.5, 92.5, hole_d, z0, z1),
    (7.5, 92.5, hole_d, z0, z1),
]:
    part = part - hole(a, b, d, lo, hi)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "LBracket_exact.step")
